INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'claims', 'Umweltbezogene Anbietererklärungen (je Aussage: Typ, Abschnitt, gedruckte Bedingung, Geltungsbereich, Kommunikationsweg, Symbol, ergänzende Erklärung, Vergleich, Zahlenblock nach §7)', 'json', NULL, false, '§7.2–§7.17, §5.6, §5.7 d), §5.8, §5.10.2, §6.3', 'Plan 3: Zeilen je Aussage — der Aussagetyp (CLAIMMAP, die 23 Token von selected_claim_type) füllt Abschnitt, gedruckte Bedingung und Zahlenblock; je Block die gedruckten Formeln als Zeilenwerte (§7.6.3 (R−E)/((R−E)+P)×100, §7.8.4 A/P×100, §7.10.3 (I−N)/I×100) und die gedruckten Prüfungen (R−E>0, 100 % bei uneingeschränkter Erneuerbarkeits-Aussage, keine uneingeschränkte CO2-neutral- / nachhaltig-Aussage, Vergleichspflicht nach 6.3) → type_ok; Anzahl → claims_count (DIN-14021-01-D1), Zeilen mit nicht erfüllter Typbedingung → claims_type_fail (-D2), spezifische Anforderungen erfüllt → specific_requirements_met_code (-D3). Die Einzelskalare bleiben (din14021-D-1 … D-24); IF-Guards der Typ-Gates STAGED (din14021-G-1 … G-27).', 'imported_unverified', '7.1.1 Abschnitt 7 gibt Erklärungen und Anwendungshinweise für ausgewählte, häufig in umweltbezogenen Anbietererklärungen verwendete Begriffe. Die Verantwortung des Antragstellers, den in diesem Abschnitt dargelegten Prinzipien zu folgen, darf nicht durch Verwendung ähnlicher Begriffe abgeschwächt werden. Abschnitt 7 ergänzt, ersetzt jedoch nicht die Anforderungen in anderen Abschnitten der vorliegenden Internationalen Norm. — a) Die Aussage darf nur erfolgen, wenn $R-E>0$.', 'register', '{"title":"Umweltbezogene Anbietererklärungen (Aussagen)","subtitle":"§7 — je Aussage eine Zeile; der Aussagetyp bestimmt die spezifischen Anforderungen (Abschnitt, gedruckte Bedingung, Zahlenblock)","add_label":"+ Aussage","placement":"section","columns":[{"key":"claim_type","label":"Aussagetyp","type":"lookup_key","required":true,"lookup":{"table_code":"CLAIMMAP"},"discriminator":true,"aria_label":"Aussagetyp (§7)"},{"key":"clause","label":"Abschnitt","type":"lookup_value","lookup":{"table_code":"CLAIMMAP","key_column":"claim_type","value":"clause"},"width":"6rem"},{"key":"numeric_block","label":"Zahlenblock (§7)","type":"lookup_value","lookup":{"table_code":"CLAIMMAP","key_column":"claim_type","value":"numeric_block"},"width":"8rem"},{"key":"condition_text","label":"Bedingung (§7.x, gedruckt)","type":"lookup_value","lookup":{"table_code":"CLAIMMAP","key_column":"claim_type","value":"condition_text"},"width":"22rem"},{"key":"comparative_required","label":"vergleichend lt. Abschnitt","type":"lookup_value","lookup":{"table_code":"CLAIMMAP","key_column":"claim_type","value":"comparative_by_clause"},"width":"6rem"},{"key":"scope","label":"Geltungsbereich","type":"enum","options":["complete_product","product_component","packaging","service_element"],"option_labels":{"complete_product":"gesamtes Produkt","product_component":"Produktbestandteil","packaging":"Verpackung","service_element":"Dienstleistungselement"},"aria_label":"Geltungsbereich der Aussage (§5.7 d)"},{"key":"channel","label":"Kommunikationsweg","type":"enum","options":["product_packaging_label","product_literature","technical_bulletin","advertising","telemarketing","digital_electronic_media"],"option_labels":{"product_packaging_label":"Produkt-/Verpackungsaufschrift","product_literature":"Produktliteratur","technical_bulletin":"technisches Bulletin","advertising":"Werbung","telemarketing":"Telemarketing","digital_electronic_media":"digitale/elektronische Medien"},"aria_label":"Kommunikationsweg der Aussage (§3.1.4)"},{"key":"symbol","label":"Symbol","type":"boolean","aria_label":"Symbol verwendet (§5.8.1)"},{"key":"mobius","label":"Drei-Pfeile-Symbol","type":"boolean","visible_when":"claim_type IN {''recyclable'', ''recycled_content''}","aria_label":"Drei-Pfeile-Symbol verwendet (§5.10.2.4, nur Recyclatgehalt / Recyclingfähigkeit)"},{"key":"explanatory","label":"ergänzende Erklärung","type":"text","aria_label":"Ergänzende Erklärung zur Aussage (§5.6)"},{"key":"unqualified","label":"uneingeschränkte Aussage","type":"boolean","visible_when":"claim_type IN {''renewable_material'', ''renewable_energy'', ''sustainable'', ''carbon_neutral''}","aria_label":"Uneingeschränkte Aussage (§7.14.2 / §7.15.2 / §7.16.1 / §7.17.3.2)"},{"key":"comparative","label":"vergleichend","type":"boolean","aria_label":"Vergleichende Aussage (§6.3)"},{"key":"comparison_basis","label":"Vergleichsbasis","type":"enum","options":["own_prior_process","own_prior_product","other_org_process","other_org_product"],"option_labels":{"own_prior_process":"eigenes vorheriges Verfahren","own_prior_product":"eigenes vorheriges Produkt","other_org_process":"Verfahren anderer Organisation","other_org_product":"Produkt anderer Organisation"},"visible_when":"comparative == true","aria_label":"Vergleichsbasis (§6.3.1 a–d)"},{"key":"comparison_months","label":"Zeitraum (Monate)","type":"number","min":0,"visible_when":"comparative == true","aria_label":"Berechnungszeitraum des Vergleichs in Monaten (§6.3.2 c, gewöhnlich 12)"},{"key":"r","label":"R","type":"number","unit":"MJ","min":0,"visible_when":"numeric_block == ''recovered_energy''","aria_label":"R — Energiemenge aus dem Prozess der Energierückgewinnung"},{"key":"e","label":"E","type":"number","unit":"MJ","min":0,"visible_when":"numeric_block == ''recovered_energy''","aria_label":"E — Energie aus Primärquellen für den Rückgewinnungsprozess"},{"key":"p","label":"P","type":"number","unit":"MJ","min":0,"visible_when":"numeric_block == ''recovered_energy''","aria_label":"P — Energie aus Primärquellen beim Herstellungsverfahren"},{"key":"net_recovered_pct","label":"Zurückgewonnene Nettoenergie (%)","type":"derived","expr":"(r - e) / ((r - e) + p) * 100","visible_when":"numeric_block == ''recovered_energy''"},{"key":"a_mass","label":"A","type":"number","unit":"kg","min":0,"visible_when":"numeric_block == ''recycled_content''","aria_label":"A — Masse des recycelten Materials"},{"key":"p_mass","label":"P","type":"number","unit":"kg","min":0,"visible_when":"numeric_block == ''recycled_content''","aria_label":"P — Produktmasse"},{"key":"recycled_pct","label":"X (%)","type":"derived","expr":"a_mass / p_mass * 100","visible_when":"numeric_block == ''recycled_content''"},{"key":"i_res","label":"I","type":"number","min":0,"visible_when":"numeric_block == ''reduced_resource''","aria_label":"I — anfänglicher Ressourcenverbrauch je Produktionseinheit"},{"key":"n_res","label":"N","type":"number","min":0,"visible_when":"numeric_block == ''reduced_resource''","aria_label":"N — neuer Ressourcenverbrauch je Produktionseinheit"},{"key":"reduced_pct","label":"U (%)","type":"derived","expr":"(i_res - n_res) / i_res * 100","visible_when":"numeric_block == ''reduced_resource''"},{"key":"renewable_pct","label":"Anteil erneuerbar (%)","type":"number","unit":"%","min":0,"max":100,"visible_when":"numeric_block IN {''renewable_material'', ''renewable_energy''}","aria_label":"Anteil erneuerbares Material / erneuerbare Energie in Prozent"},{"key":"carbon_footprint","label":"CO2-Fußabdruck (ISO/TS 14067)","type":"number","unit":"kg CO2e","visible_when":"numeric_block == ''carbon''","aria_label":"Carbon Footprint des Produktes nach ISO/TS 14067"},{"key":"carbon_offset_declared","label":"Ausgleich erklärt","type":"boolean","visible_when":"claim_type == ''carbon_neutral''","aria_label":"Ausgleich erklärt — Carbon Footprint angegeben und Ausgleich erläutert (§7.17.3.3)"},{"key":"recovered_ok","label":"§7.6.3 a)","type":"derived","expr":"if(numeric_block == ''recovered_energy'', if(r IS NULL OR e IS NULL, 0, if(r - e > 0, 1, 0)), 1)","display":"badge","value_labels":{"0":"R−E>0 nicht erfüllt oder R / E nicht eingetragen (§7.6.3 a)","1":"R−E>0 erfüllt (oder nicht zutreffend; Nettoenergie erst mit P)"}},{"key":"renewable_ok","label":"§7.14.2 / §7.15.2","type":"derived","expr":"if(numeric_block IN {''renewable_material'', ''renewable_energy''}, if(unqualified == true, if(renewable_pct IS NULL, 0, if(renewable_pct == 100, 1, 0)), 1), 1)","display":"badge","value_labels":{"0":"uneingeschränkte Aussage ohne 100 % (§7.14.2 / §7.15.2)","1":"100 % erfüllt, eingeschränkte Aussage oder nicht zutreffend"}},{"key":"unqualified_ok","label":"§7.16.1 / §7.17.3.2","type":"derived","expr":"if(claim_type IN {''carbon_neutral'', ''sustainable''}, if(unqualified == true, 0, 1), 1)","display":"badge","value_labels":{"0":"uneingeschränkte Aussage unzulässig (§7.16.1 / §7.17.3.2)","1":"zulässig (eingeschränkt oder nicht zutreffend)"}},{"key":"comparative_ok","label":"§6.3","type":"derived","expr":"if(comparative_required == true, if(comparative == true, 1, 0), 1)","display":"badge","value_labels":{"0":"Aussagetyp ist vergleichend (6.3), Vergleich nicht angegeben","1":"Vergleichspflicht erfüllt oder nicht zutreffend"}},{"key":"type_ok","label":"Typbedingung erfüllt","type":"derived","expr":"if(recovered_ok == 1 AND renewable_ok == 1 AND unqualified_ok == 1 AND comparative_ok == 1, 1, 0)","display":"badge","value_labels":{"0":"Typbedingung nicht erfüllt","1":"Typbedingung erfüllt"}}],"footer":["claims_count","claims_type_fail","specific_requirements_met_code"],"note":"7.1.1 Abschnitt 7 gibt Erklärungen und Anwendungshinweise für ausgewählte, häufig in umweltbezogenen Anbietererklärungen verwendete Begriffe. Die Verantwortung des Antragstellers, den in diesem Abschnitt dargelegten Prinzipien zu folgen, darf nicht durch Verwendung ähnlicher Begriffe abgeschwächt werden. Abschnitt 7 ergänzt, ersetzt jedoch nicht die Anforderungen in anderen Abschnitten der vorliegenden Internationalen Norm. Je Aussage eine Zeile; der Aussagetyp füllt Abschnitt, gedruckte Bedingung und Zahlenblock aus CLAIMMAP. Die Zahlenspalten des gewählten Blocks sind Zwillinge der Einzelfelder auf DIN-14021-05 (R/E/P → EQ-01, A/P → EQ-02, I/N → EQ-03, Anteile, Carbon Footprint) und die Kopfspalten Zwillinge von selected_claim_type / claim_scope / communication_channel / symbol_used (-01), mobius_loop_used / explanatory_statement (-03), comparative_claim / comparison_basis / comparison_time_interval (-04) — die Einzelfelder bleiben bis zur Ratifizierung (din14021-D-1 … D-24). Die gedruckte Bedingung („darf nur … wenn“) ist je Zeile vom Ingenieur zu beurteilen (din14021-J-4); nur R−E>0, die 100 % der uneingeschränkten Erneuerbarkeits-Aussagen, das Verbot der uneingeschränkten „CO2-neutral“- / „nachhaltig“-Aussage und die Vergleichspflicht der fünf vergleichenden Aussagetypen sind als Zeilenprüfung berechnet (type_ok). Die 18 Typ-Gates REQ-28 … REQ-45 auf -01 und die Zahlen-Gates REQ-20 … REQ-25 / REQ-49 auf -05 sind heute unbedingt — IF-Guards STAGED (din14021-G-1 … G-27)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'claims') AND w.code = 'DIN-14021-01' AND s.code = 'DIN-14021';
