SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'specific_requirements_met_code', 'Spezifische Anforderungen erfüllt (1 = jede Aussage besteht ihre Typprüfung, 0 = sonst oder keine Aussage erfasst)', 'number', NULL, false, '§7', 'Plan 3: Ausgabe der Gleichung DIN-14021-01-D3 — 1, wenn mindestens eine Aussage erfasst ist und keine Zeile type_ok == 0 hat (leeres Register ⇒ 0, nie ein Phantom-Pass); Zwilling des Hand-Booleans specific_requirements_met auf DIN-14021-06 („Aggregat“, din14021-D-25) — Vererbung nach -06 STAGED (din14021-C-1).', 'imported_unverified', '7.1.1 Abschnitt 7 gibt Erklärungen und Anwendungshinweise für ausgewählte, häufig in umweltbezogenen Anbietererklärungen verwendete Begriffe. Die Verantwortung des Antragstellers, den in diesem Abschnitt dargelegten Prinzipien zu folgen, darf nicht durch Verwendung ähnlicher Begriffe abgeschwächt werden. Abschnitt 7 ergänzt, ersetzt jedoch nicht die Anforderungen in anderen Abschnitten der vorliegenden Internationalen Norm. — a) Die Aussage darf nur erfolgen, wenn $R-E>0$.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'specific_requirements_met_code') AND w.code = 'DIN-14021-01' AND s.code = 'DIN-14021';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'general_requirements_items', 'Allgemeine Anforderungen §5.3 – §5.10 (Prüfliste, Mehrfachauswahl)', 'json', NULL, false, '§5.3–§5.10', 'Plan 3: Mehrfachauswahl über die acht gedruckten Abschnitte 5.3 … 5.10 (S5_3_5_10); die zwölf Einzel-Booleans bleiben (din14021-D-26 … D-35); general_requirements_met_code ist STAGED (din14021-F-1 — seit Plan 3 Welle A erreicht contains() den Materialisierer; der Block bleibt bis zur Ratifizierung STAGED).', 'imported_unverified', 'Die in Abschnitt 5 aufgeführten Anforderungen gelten für sämtliche umweltbezogenen Anbietererklärungen, unabhängig davon, ob es eine von den ausgewählten Aussagen ist, auf die in Abschnitt 7 verwiesen wird, oder eine sonstige Umweltaussage. — Umweltbezogene Anbietererklärungen und ergänzende Erklärungen sind Gegenstand aller Anforderungen in 5.7. Derartige Aussagen, einschließlich jeder ergänzenden Erklärung:', 'select_many', '{"title":"Anforderungen an alle umweltbezogenen Anbietererklärungen (§5.3 – §5.10)","subtitle":"„Die in Abschnitt 5 aufgeführten Anforderungen gelten für sämtliche umweltbezogenen Anbietererklärungen“ — ankreuzen, welche Abschnitte geprüft und erfüllt sind","note":"Die in Abschnitt 5 aufgeführten Anforderungen gelten für sämtliche umweltbezogenen Anbietererklärungen, unabhängig davon, ob es eine von den ausgewählten Aussagen ist, auf die in Abschnitt 7 verwiesen wird, oder eine sonstige Umweltaussage. Die zwölf Einzel-Booleans dieses Arbeitsblatts (5.3 … 5.7 a/b/h/i/r, 5.8.3, 5.8.5, 5.10.2) bleiben bis zur Ratifizierung (din14021-D-26 … D-35); ein Vollständigkeits-Code (alle acht angekreuzt) ist nicht materialisierbar — der Materialisierer liest keine Checklisten (din14021-F-1).","groups":[{"label":"§5.3 – §5.10","options":["5.3 Unbestimmte oder unspezifische Aussagen","5.4 Aussagen von „... frei“","5.5 Aussagen zur Nachhaltigkeit","5.6 Anwendung von ergänzenden Erklärungen","5.7 Besondere Anforderungen","5.8 Verwendung von Symbolen für Umweltaussagen","5.9 Sonstige Informationen oder Aussagen","5.10 Spezifische Symbole"]}]}'::jsonb, NULL, NULL, '[{"value":"5.3 Unbestimmte oder unspezifische Aussagen","label_de":"5.3 Unbestimmte oder unspezifische Aussagen","order_index":0},{"value":"5.4 Aussagen von „... frei“","label_de":"5.4 Aussagen von „... frei“","order_index":1},{"value":"5.5 Aussagen zur Nachhaltigkeit","label_de":"5.5 Aussagen zur Nachhaltigkeit","order_index":2},{"value":"5.6 Anwendung von ergänzenden Erklärungen","label_de":"5.6 Anwendung von ergänzenden Erklärungen","order_index":3},{"value":"5.7 Besondere Anforderungen","label_de":"5.7 Besondere Anforderungen","order_index":4},{"value":"5.8 Verwendung von Symbolen für Umweltaussagen","label_de":"5.8 Verwendung von Symbolen für Umweltaussagen","order_index":5},{"value":"5.9 Sonstige Informationen oder Aussagen","label_de":"5.9 Sonstige Informationen oder Aussagen","order_index":6},{"value":"5.10 Spezifische Symbole","label_de":"5.10 Spezifische Symbole","order_index":7}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'general_requirements_items') AND w.code = 'DIN-14021-03' AND s.code = 'DIN-14021';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'documentation_items', 'Mindestangaben der Dokumentation §6.5.3 a) – g) (Prüfliste, Mehrfachauswahl)', 'json', NULL, false, '§6.5.3', 'Plan 3: Mehrfachauswahl über die sieben gedruckten Mindestangaben a) – g) (S6_5_3); das Einzelfeld info_documented_min bleibt (din14021-D-36); verification_requirements_met_code ist STAGED (din14021-F-1).', 'imported_unverified', '6.5.3 Die Mindestangaben, die nach 6.2 zu dokumentieren und aufzubewahren sind, müssen Folgendes enthalten: — a) Angabe der angewendeten Norm oder des angewendeten Verfahrens;', 'select_many', '{"title":"Mindestangaben der Dokumentation (§6.5.3 a) – g))","subtitle":"„Die Mindestangaben, die nach 6.2 zu dokumentieren und aufzubewahren sind, müssen Folgendes enthalten:“ — ankreuzen, was dokumentiert und aufbewahrt ist","note":"6.5.3 Die Mindestangaben, die nach 6.2 zu dokumentieren und aufzubewahren sind, müssen Folgendes enthalten: Das Einzelfeld info_documented_min (ein Boolean für alle sieben) bleibt bis zur Ratifizierung (din14021-D-36); REQ-19 liest heute den Skalar — ein Vollständigkeits-Code ist nicht materialisierbar (din14021-F-1).","groups":[{"label":"§6.5.3 a) – g)","options":["a) Angabe der angewendeten Norm oder des angewendeten Verfahrens;","b) Dokumente/Unterlagen, falls die Überprüfung der Aussage nicht durch Prüfung des Endproduktes erfolgen kann;","c) Prüfergebnisse für den Fall, dass diese zur Überprüfung der Aussage notwendig sind;","d) bei Prüfung durch eine unabhängige Prüfstelle, deren Name und Adresse;","e) Nachweis, dass die Aussage mit den Anforderungen von 5.7 h ) und 5.7 r ) übereinstimmt;","f) sofern die umweltbezogene Anbietererklärung einen Vergleich mit anderen Produkten enthält, eine eindeutige Beschreibung des angewendeten Verfahrens, der Ergebnisse von Prüfungen dieser Produkte und alle Annahmen;","g) Nachweis, dass die Bewertung des Antragstellers die Gewissheit bietet, dass die umweltbezogene Anbietererklärung während des Zeitraumes, für den das Produkt auf dem Markt angeboten wird, und für einen angemessenen Zeitraum danach weiterhin richtig ist, wobei die Lebensdauer des Produktes zu berücksichtigen ist."]}]}'::jsonb, NULL, NULL, '[{"value":"a) Angabe der angewendeten Norm oder des angewendeten Verfahrens;","label_de":"a) Angabe der angewendeten Norm oder des angewendeten Verfahrens;","order_index":0},{"value":"b) Dokumente/Unterlagen, falls die Überprüfung der Aussage nicht durch Prüfung des Endproduktes erfolgen kann;","label_de":"b) Dokumente/Unterlagen, falls die Überprüfung der Aussage nicht durch Prüfung des Endproduktes erfolgen kann;","order_index":1},{"value":"c) Prüfergebnisse für den Fall, dass diese zur Überprüfung der Aussage notwendig sind;","label_de":"c) Prüfergebnisse für den Fall, dass diese zur Überprüfung der Aussage notwendig sind;","order_index":2},{"value":"d) bei Prüfung durch eine unabhängige Prüfstelle, deren Name und Adresse;","label_de":"d) bei Prüfung durch eine unabhängige Prüfstelle, deren Name und Adresse;","order_index":3},{"value":"e) Nachweis, dass die Aussage mit den Anforderungen von 5.7 h ) und 5.7 r ) übereinstimmt;","label_de":"e) Nachweis, dass die Aussage mit den Anforderungen von 5.7 h ) und 5.7 r ) übereinstimmt;","order_index":4},{"value":"f) sofern die umweltbezogene Anbietererklärung einen Vergleich mit anderen Produkten enthält, eine eindeutige Beschreibung des angewendeten Verfahrens, der Ergebnisse von Prüfungen dieser Produkte und alle Annahmen;","label_de":"f) sofern die umweltbezogene Anbietererklärung einen Vergleich mit anderen Produkten enthält, eine eindeutige Beschreibung des angewendeten Verfahrens, der Ergebnisse von Prüfungen dieser Produkte und alle Annahmen;","order_index":5},{"value":"g) Nachweis, dass die Bewertung des Antragstellers die Gewissheit bietet, dass die umweltbezogene Anbietererklärung während des Zeitraumes, für den das Produkt auf dem Markt angeboten wird, und für einen angemessenen Zeitraum danach weiterhin richtig ist, wobei die Lebensdauer des Produktes zu berücksichtigen ist.","label_de":"g) Nachweis, dass die Bewertung des Antragstellers die Gewissheit bietet, dass die umweltbezogene Anbietererklärung während des Zeitraumes, für den das Produkt auf dem Markt angeboten wird, und für einen angemessenen Zeitraum danach weiterhin richtig ist, wobei die Lebensdauer des Produktes zu berücksichtigen ist.","order_index":6}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'documentation_items') AND w.code = 'DIN-14021-04' AND s.code = 'DIN-14021';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'unqualified_claim', 'Uneingeschränkte Aussage (§7.14.2 / §7.15.2: nur bei 100 %; §7.16.1 / §7.17.3.2: unzulässig)', 'boolean', NULL, false, '§7.14.2, §7.15.2, §7.16.1, §7.17.3.2', 'Plan 3: der in den Prod-Validierungsregeln genannte, aber nicht vorhandene Treiber („renewable_material_pct eq 100 when unqualified_claim“) — Bestätigung, dass die Aussage uneingeschränkt gemacht wird; nur für die vier Aussagetypen sichtbar, deren Abschnitt eine „uneingeschränkte Aussage“ regelt; die 100-%-Gates (REQ-22 / REQ-23) und das Verbot (CO2-neutral / nachhaltig) sind STAGED (din14021-G-25 / G-26 / G-27); die Registerspalte unqualified ist der Zwilling je Zeile (din14021-D-11).', 'imported_unverified', 'Eine uneingeschränkte Aussage zur Erneuerbarkeit ist nur zulässig, wenn das Produkt zu 100 \% aus erneuerbarem Material besteht, wobei nur geringfügige Anteile an nicht erneuerbarem Material in diesem Material erlaubt sind. Andernfalls müssen Aussagen zur Erneuerbarkeit wie folgt eingeschränkt werden:
a) wenn eine Aussage zum Gehalt an erneuerbarem Material gemacht wird, muss der prozentuale Massenanteil von erneuerbarem Material angegeben werden;
b) der prozentuale Anteil von erneuerbarem Material (Massenanteil) in Produkten und in Verpackungen muss getrennt angegeben werden und darf nicht zusammengefasst werden. — Eine uneingeschränkte Aussage zur erneuerbaren Energie ist nur zulässig, wenn 100 \% der Energie erneuerbar ist. Andernfalls müssen Aussagen zur erneuerbaren Energie wie folgt eingeschränkt werden.', 'attestation', NULL, NULL, 'selected_claim_type IN {''renewable_material'', ''renewable_energy'', ''sustainable'', ''carbon_neutral''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'unqualified_claim') AND w.code = 'DIN-14021-05' AND s.code = 'DIN-14021';
COMMIT;
